TESTS = ["test_unit_type_core_slice.py"]


def schema_key(type_name: str, status: str, method: str, expr: str, rule: str) -> dict:
    return {"type": type_name, "status": status, "java_source": SOURCE, "java_method": method, "java_expr": expr, "rule": rule}


def symbol(owner: str, name: str, godot_symbol: str, method: str, expression: str, rule: str, status: str = "source-backed") -> tuple[str, dict]:
    return name, {"status": status, "godot_owner": owner, "godot_symbol": godot_symbol, "rule": rule, "tests": TESTS, "runtime_proof": PROOF, "java_source": SOURCE, "java_method": method, "java_expr": expression}


def register_slice(slice_id: str, owner: str, method: str, expressions: list[str], symbols: list[tuple[str, dict]], params: list[dict], return_keys: list[str], schemas: dict[str, dict]) -> None:
    source_symbols.upsert_source_slice(GODOT, slice_id, {"status": "done", "java_source": SOURCE, "java_class": "mindustry.type.UnitType", "java_method": method, "godot_owner": owner, "exact_exprs": expressions, "source_symbols": [name for name, _entry in symbols], "tests": TESTS, "runtime_proof": PROOF})
    source_symbols.upsert_source_api_contract(GODOT, owner, {"status": "active", "source_slice": slice_id, "java_source": SOURCE, "source_method": method, "params": params, "return_keys": return_keys, "tests": TESTS, "runtime_proof": PROOF, "rule": f"Canonical UnitType runtime contract for {method}; dependencies are explicit."})
    for name, entry in schemas.items():
        source_symbols.upsert_source_state_schema(GODOT, name, entry)


